export async function POST(request: Request) {
  const body = await request.text();
  const signature = request.headers.get("x-shopify-hmac-sha256");
  if (!verifyWebhook(body, signature)) {
    return new Response("Invalid signature", { status: 401 });
  }

  const topic = request.headers.get("x-shopify-topic") ?? "";
  const { handle } = JSON.parse(body);

  if (topic.startsWith("products/")) revalidateTag(`product:${handle}`);
  if (topic.startsWith("collections/")) revalidateTag(`collection:${handle}`);

  return Response.json({ revalidated: true, topic });
}

// Upload only the vehicles that moved since the last frame.
export function syncPositions(gl: WebGL2RenderingContext, buffer: WebGLBuffer, fleet: Fleet) {
  gl.bindBuffer(gl.ARRAY_BUFFER, buffer);

  for (const { start, end } of fleet.dirtyRanges()) {
    const view = fleet.positions.subarray(start * 2, end * 2);
    gl.bufferSubData(gl.ARRAY_BUFFER, start * 2 * Float32Array.BYTES_PER_ELEMENT, view);
  }

  fleet.clearDirty();
}

// uProgress is 0 at the top of a project and 1 at the end.
float lightMask(vec2 uv, float progress) {
  vec2 source = vec2(mix(-0.2, 1.2, progress), 0.8);
  float falloff = smoothstep(0.9, 0.1, distance(uv, source));
  float daylight = 0.6 + 0.4 * sin(progress * 3.14159);
  return falloff * daylight;
}

void main() {
  vec3 base = texture(uImage, vUv).rgb;
  float light = lightMask(vUv, uProgress);
  fragColor = vec4(base * (0.35 + light), 1.0);
}

export function applyRemote(doc: Y.Doc, update: Uint8Array, origin: Peer) {
  Y.applyUpdate(doc, update, origin);

  // Persist the merged state, not the raw update, so startup is a single read.
  db.prepare("UPDATE notes SET state = ?, updated_at = ? WHERE id = ?")
    .run(Y.encodeStateAsUpdate(doc), Date.now(), doc.guid);
}

